<template>
  <div class="page-backup-management">
    <div class="page-header">
      <h2>{{ t('settings.backups.title') }}</h2>
      <el-button type="primary" :loading="creating" @click="onCreateBackup">
        {{ t('settings.backups.backupNow') }}
      </el-button>
    </div>

    <el-card>
      <el-table v-loading="loading" :data="backups" stripe>
        <el-table-column prop="filename" :label="t('settings.backups.filename')" min-width="220" />
        <el-table-column prop="size_bytes" :label="t('settings.backups.size')" width="120">
          <template #default="{ row }">
            {{ formatSize(row.size_bytes) }}
          </template>
        </el-table-column>
        <el-table-column prop="created_at" :label="t('common.createdAt')" width="180">
          <template #default="{ row }">
            {{ formatDate(row.created_at) }}
          </template>
        </el-table-column>
        <el-table-column prop="verified" :label="t('settings.backups.integrity')" width="100">
          <template #default="{ row }">
            <el-tag :type="row.verified ? 'success' : 'danger'" size="small">
              {{ row.verified ? t('settings.backups.verified') : t('settings.backups.unverified') }}
            </el-tag>
          </template>
        </el-table-column>
        <el-table-column :label="t('common.actions')" width="200" fixed="right">
          <template #default="{ row }">
            <ConfirmButton
              :title="t('settings.backups.confirmRestore')"
              confirm-button-type="warning"
              @confirm="onRestore(row)"
            >
              <el-button link type="primary" size="small">{{ t('common.restore') }}</el-button>
            </ConfirmButton>
            <ConfirmButton
              :title="t('settings.backups.confirmDelete')"
              confirm-button-type="danger"
              @confirm="onDelete(row)"
            >
              <el-button link type="danger" size="small">{{ t('common.delete') }}</el-button>
            </ConfirmButton>
          </template>
        </el-table-column>
      </el-table>

      <el-empty v-if="!loading && backups.length === 0" :description="t('settings.backups.empty')" />
    </el-card>
  </div>
</template>

<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { useI18n } from 'vue-i18n'
import { ElMessage } from 'element-plus'
import { createBackup, deleteBackup, getBackups, restoreBackup, type BackupRead } from '@/api/backup'
import ConfirmButton from '@/components/common/ConfirmButton.vue'
import { showError } from '@/utils/error'

const { t } = useI18n()
const backups = ref<BackupRead[]>([])
const loading = ref(false)
const creating = ref(false)

function formatSize(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`
  return `${(bytes / (1024 * 1024)).toFixed(2)} MB`
}

function formatDate(value: string): string {
  const date = new Date(value)
  return date.toLocaleString()
}

async function loadBackups() {
  loading.value = true
  try {
    backups.value = await getBackups()
  } catch (error) {
    showError(error, t('settings.backups.loadFailed'))
  } finally {
    loading.value = false
  }
}

async function onCreateBackup() {
  creating.value = true
  try {
    const backup = await createBackup()
    ElMessage.success(t('settings.backups.created', { filename: backup.filename }))
    loadBackups()
  } catch (error) {
    showError(error, t('settings.backups.createFailed'))
  } finally {
    creating.value = false
  }
}

async function onRestore(row: BackupRead) {
  try {
    const response = await restoreBackup(row.filename)
    ElMessage.success(response.message)
    loadBackups()
  } catch (error) {
    showError(error, t('settings.backups.restoreFailed'))
  }
}

async function onDelete(row: BackupRead) {
  try {
    await deleteBackup(row.filename)
    ElMessage.success(t('settings.backups.deleted'))
    loadBackups()
  } catch (error) {
    showError(error, t('settings.backups.deleteFailed'))
  }
}

onMounted(() => {
  loadBackups()
})
</script>

<style scoped>
.page-backup-management {
  padding: 0;
}

.page-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 20px;
}

.page-header h2 {
  margin: 0;
}
</style>
