import apiClient from './client'

export interface BackupRead {
  filename: string
  size_bytes: number
  created_at: string
  verified: boolean
}

export interface BackupResponse {
  message: string
  backup: BackupRead | null
}

export async function getBackups(): Promise<BackupRead[]> {
  const response = await apiClient.get<BackupRead[]>('/v1/backups')
  return response.data
}

export async function createBackup(): Promise<BackupRead> {
  const response = await apiClient.post<BackupRead>('/v1/backups')
  return response.data
}

export async function restoreBackup(filename: string): Promise<BackupResponse> {
  const response = await apiClient.post<BackupResponse>(`/v1/backups/${encodeURIComponent(filename)}/restore`)
  return response.data
}

export async function deleteBackup(filename: string): Promise<void> {
  await apiClient.delete(`/v1/backups/${encodeURIComponent(filename)}`)
}
